import{_ as t,H as i,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"10 | TDD中的驱动（3）：何为经典学派？何为伦敦学派？","description":"","frontmatter":{},"headers":[{"level":2,"title":"命令行解析","slug":"命令行解析","link":"#命令行解析","children":[]},{"level":2,"title":"与经典模式的差异","slug":"与经典模式的差异","link":"#与经典模式的差异","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·TDD项目实战70讲/10｜TDD中的驱动（3）：何为经典学派？何为伦敦学派？.md","filePath":"徐昊·TDD项目实战70讲/10｜TDD中的驱动（3）：何为经典学派？何为伦敦学派？.md","lastUpdated":1795563222000}'),p={name:"徐昊·TDD项目实战70讲/10｜TDD中的驱动（3）：何为经典学派？何为伦敦学派？.md"};function s(n,e,E,o,r,h){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_10-tdd中的驱动-3-何为经典学派-何为伦敦学派" tabindex="-1">10 | TDD中的驱动（3）：何为经典学派？何为伦敦学派？ <a class="header-anchor" href="#_10-tdd中的驱动-3-何为经典学派-何为伦敦学派" aria-label="Permalink to &quot;10 | TDD中的驱动（3）：何为经典学派？何为伦敦学派？&quot;">​</a></h1><p>你好，我是徐昊。今天我们继续来讨论测试驱动开发中的驱动。</p><p>上节课我们讲了四种常用的重构手法，分别是提取方法、内联方法、引入参数和引入字段。并区分了用于高效修改代码的重构手法，和用于消除坏味道以改进架构设计的重构。还介绍了一种架构软件的方法：重构到模式。也就是通过重构将坏味道替换为模式，从而改进软件架构的方式。</p><p>重构到模式，或者说 TDD 红 / 绿 / 重构循环中的重构，是在完成功能的前提下以演进的方式进行设计。这是延迟性决策策略，也叫最晚尽责时刻（Last Responsible Moment，LRM）。也就是说，与其在信息不足的情况下做决定，不如延迟到信息更多，或是不得不做出决策的时机再决策。这种策略的重点在于，在保持决策有效性的前提下，尽可能地推迟决策时间。</p><p>如果架构愿景不清晰，那么“最晚尽责时刻”让我们不必花费时间进行空对空的讨论，可以尽早开始实现功能，再通过重构从可工作的软件（Working Software）中提取架构。这种方式也被称作 TDD 的经典学派（Classic School）或芝加哥学派（Chicago School）。</p><p>除了经典学派之外，还有一种 TDD 风格，被称作 TDD 的伦敦学派（London School）。如果架构愿景已经比较清晰了，那么我们就可以使用伦敦学派进行 TDD。</p><h2 id="命令行解析" tabindex="-1">命令行解析 <a class="header-anchor" href="#命令行解析" aria-label="Permalink to &quot;命令行解析&quot;">​</a></h2><p>伦敦学派的做法是这样的：</p><ul><li><p>按照功能需求与架构愿景划分对象的角色和职责；</p></li><li><p>根据角色与职责，明确对象之间的交互；</p></li><li><p>按照调用栈（Call Stack）的顺序，自外向内依次实现不同的对象；</p></li><li><p>在实现的过程中，依照交互关系，使用测试替身替换所有与被实现对象直接关联的对象；</p></li><li><p>直到所有对象全部都实现完成。</p></li></ul><p>接下来我仍然以命令行参数解析为例，演示一下如何通过伦敦学派的方式来开发它。</p><p>首先是明确我们的架构愿景，也就是对象的角色与职责划分。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/10/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/10/1.png" alt=""></a></p><p>如上图所示，在系统中一共存在四个类：作为对外 API 的 Args，从参数列表中提取参数的ValueRetriever，将 Java 类对象封装为选项的 OptionClass，以及根据类型和数据解析参数的OptionParser。它们的交互，也如上图所示。</p><p>在划定角色和职责之后，我们来依次实现它们。视频演示如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/10/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/10/2.jpeg" alt=""></a></p><h2 id="与经典模式的差异" tabindex="-1">与经典模式的差异 <a class="header-anchor" href="#与经典模式的差异" aria-label="Permalink to &quot;与经典模式的差异&quot;">​</a></h2><p>通过上面的视频展示，你能明显体会到“伦敦学派”与“经典学派”的差异：</p><ul><li><p>经典学派强调功能优先，设计 / 架构后置，通过重构进行演进式设计。</p></li><li><p>而“伦敦学派”并不排斥预先存在的设计，更强调如何通过测试替身，将注意力集中到功能上下文中的某个对象上。然后在测试的驱动下，按部就班地完成功能开发。</p></li></ul><p>然而二者其实并没有什么冲突。回顾一下第八讲的演示，以及本节课介绍伦敦学派时的演示，你会发现二者有相似之处：都不是将功能整体作为单元的粒度，而是选择了更小的范围。所不同的仅仅在于，在本节课中，我们更为细致地划分了功能上下文（也就是做了更多的设计）。</p><p>所以我们可以将伦敦学派看作一种利用架构愿景分割功能上下文，然后再进入经典模式的TDD 方法。这么做的好处是，对于复杂的场景，可以极大简化构造测试的时间。下面让我们看一个例子：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/10/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/10/3.jpeg" alt=""></a></p><p>在这个例子里，我们可以通过重构去获得想要的架构，比如提取出 Repository 等。但是，以经典学派构造测试过于麻烦，而如果以伦敦学派开始就可以简单很多：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/10/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/10/4.jpeg" alt=""></a></p><p>需要提醒一下，经典学派和伦敦学派是 TDD 中都需要掌握的基本功。在功能上下文内，以经典学派为主；而跨功能上下文时，可以使用伦敦学派对不同的功能上下文进行隔离。</p><p>顺便说一句，曾经有一段时间，TDD 社区内将这两种风格对立起来：</p><ul><li><p>经典学派质疑伦敦学派向预先设计妥协，放弃了演进式架构。</p></li><li><p>伦敦学派攻击经典学派不愿吸收借鉴行业积累，“难道每次都要从一个大类重构到 MVC吗？”</p></li></ul><p>然而这种分歧是无意义的。在不同的场合下，我们只需要使用该用的方式就好。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>通过第 8-10 这三节课，我们讨论了测试驱动中的驱动。也回答了测试驱动到底能够驱动什么：单元级别功能测试能够驱动其对应单元（功能上下文或变化点）的功能需求。而对于单元之内某个功能的实现，则无能为力。</p><p>从“驱动”的角度来说，TDD 实际上并不是一种编码技术，更像是一种架构技术，它可以帮助你更好地将功能放置到不同的单元。于是我们继续介绍了 TDD 中两种处理架构的思路：延迟性决策的经典学派和通过架构愿景划分功能上下文的伦敦学派。</p><p>至此，我们已经对测试驱动开发有了较深入的了解，知道了什么样的测试，提供什么样的驱动。那么下节课，让我们看看测试驱动开发的全貌。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在伦敦学派中，是如何保证测试的有效性的？</p><p>编辑来信：</p><ul><li><p>TDD 是一项技能，唯有动手实操、反复练习，才能有所小成。为了帮助你更快地进步，徐昊老师特发起了“代码评点”活动。</p></li><li><p>在第一个实战项目结束后，我们会根据你提交的学习反馈，手动选出其中几位进行代码评点与解疑答惑。而评点的详细内容我们也将制成加餐，展示在专栏里，供其他同学学习与参考。</p></li><li><p>划重点！如果学完第 1-10 讲再写反馈，将会大大提高你入选的机会！另，此次收集时间截至 4 月 3 日零点。所以非常希望你能跟上我们的更新进度，多动手实操，并记录学习体会。</p></li><li><p>最后，希望我们都能好好学习，更上层楼！</p></li></ul>',35)])])}const g=t(p,[["render",s]]);export{c as __pageData,g as default};
